# Let me fetch all 1001 records in batches and filter them
import re
from datetime import datetime

def parse_subname_fields(subtype_str, subname_str):
    """Parse the subtype/subname fields into a dictionary"""
    if not subtype_str or not subname_str:
        return {}
    subtypes = subtype_str.split('|')
    subnames = subname_str.split('|')
    result = {}
    for i, key in enumerate(subtypes):
        if i < len(subnames):
            result[key] = subnames[i]
    return result

