# The parser is interpreting '2016' and 'Aug-2016' in strange ways. Let me fix this.
from datetime import datetime
from dateutil import parser as date_parser

def parse_collection_date(date_str):
    """Parse collection date in various formats to datetime"""
    if not date_str or date_str == '':
        return None

    # If just a year, return Jan 1 of that year
    if date_str.isdigit() and len(date_str) == 4:
        return datetime(int(date_str), 1, 1)

    # If format is Mon-YYYY, return first day of that month
    if len(date_str) == 8 and date_str[3] == '-' and date_str[4:].isdigit():
        # e.g., "Aug-2016"
        try:
            return datetime.strptime(date_str, '%b-%Y')
        except:
            pass

    # Otherwise, try dateutil parser
    try:
        dt = date_parser.parse(date_str, dayfirst=True)
        return dt
    except:
        return None

# Test parsing
