# I need to download sequences for all 382 accessions and count N's.
# Let me use the NCBI efetch API to get sequences in FASTA format.
# I'll process in batches to avoid overwhelming the API.

import time

def fetch_sequences_batch(accessions_batch, db="nucleotide"):
    """Fetch FASTA sequences for a batch of accessions using Entrez efetch."""
    ids = ",".join(accessions_batch)
    url = "https://eutils.ncbi.nlm.nih.gov/entrez/eutils/efetch.fcgi"
    params = {
        "db": db,
        "id": ids,
        "rettype": "fasta",
        "retmode": "text",
        "tool": "python_analysis",
        "email": "analysis@example.com"
    }
    response = requests.get(url, params=params)
    return response.text

def parse_fasta(fasta_text):
    """Parse FASTA text and return dict of {accession: sequence}."""
    sequences = {}
    current_acc = None
    current_seq = []

    for line in fasta_text.strip().split('\n'):
        if line.startswith('>'):
            if current_acc is not None:
                sequences[current_acc] = ''.join(current_seq)
            # Extract accession from header
            header = line[1:].split()[0]
            current_acc = header
            current_seq = []
        else:
            current_seq.append(line.strip())

    if current_acc is not None:
        sequences[current_acc] = ''.join(current_seq)

    return sequences

# Process in batches of 50
batch_size = 50
all_sequences = {}

for i in range(0, len(accessions), batch_size):
    batch = accessions[i:i+batch_size]
    print(f"Fetching batch {i//batch_size + 1}/{(len(accessions)-1)//batch_size + 1} ({len(batch)} accessions)...")

    fasta_text = fetch_sequences_batch(batch)
    seqs = parse_fasta(fasta_text)
    all_sequences.update(seqs)

    print(f"  Retrieved {len(seqs)} sequences (total: {len(all_sequences)})")
    time.sleep(1)  # Rate limiting

print(f"\nTotal sequences retrieved: {len(all_sequences)}")
