ax2.legend(fontsize=9)

# Panel 3: Release date distribution
ax3 = axes[2]
years = filtered_df['release_date'].dt.year
ax3.hist(years, bins=range(1990, 2027), color='#2ecc71', edgecolor='black', alpha=0.7)
ax3.set_xlabel('Release Year', fontsize=10)
ax3.set_ylabel('Count of Sequences', fontsize=10)
ax3.set_title(f'Release Year Distribution\n({len(filtered_df)} final sequences)', fontsize=12, fontweight='bold')
ax3.tick_params(axis='x', rotation=45)

plt.tight_layout()
plt.savefig('viral_sequence_filtering_summary.png', dpi=150, bbox_inches='tight')
